	/** 
	 * jumpstart the process by instantiating2 Campaign
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		campaignId = CampaignService.getCampaignInstance()
		.createCampaign( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		CampaignService.getCampaignInstance()
				.createCampaign( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.campaignSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Campaign : " + successValue.getCampaignId());
							  if (successValue.getCampaignId().equals(campaignId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfCampaignList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Campaign test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on campaign consumed")
					);
			subscriber.campaignSubscribe( campaignId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Campaign : " + successValue.getCampaignId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfCampaignList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on campaign for campaignId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Campaign. 
	 */
	protected Campaign read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Campaign" );

		Campaign entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Campaign with primary key" );
		msg.append( campaignId );
		
		CampaignFetchOneSummary fetchOneSummary = new CampaignFetchOneSummary( campaignId );

		try {
			entity = CampaignService.getCampaignInstance().getCampaign( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Campaign " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Campaign.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Campaign." );

		StringBuilder msg = new StringBuilder( "Failed to update a Campaign : " );        
		Campaign entity = read();
		UpdateCampaignCommand command = generateUpdateCommand();
		command.setCampaignId(entity.getCampaignId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Campaign." );

			// for use later on...
			campaignId = entity.getCampaignId();

			CampaignService proxy = CampaignService.getCampaignInstance();  

			proxy.updateCampaign( command ).get();

			LOGGER.info( "-- Successfully saved Campaign - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + campaignId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Campaign.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Campaign." );

		Campaign entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Campaign with id " + campaignId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Campaign with id " + campaignId );

			throw e;
		}

		try{
			CampaignService.getCampaignInstance().delete( new DeleteCampaignCommand( entity.getCampaignId() ) ).get();
			LOGGER.info( "-- Successfully deleted Campaign with id " + campaignId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Campaign with id " + campaignId );

			throw e;
		}
	}

	/**
	 * get all Campaigns.
	 */
	protected List<Campaign> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Campaigns:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Campaign : " );        
		List<Campaign> collection  = new ArrayList<>();

		try {
			// call the static get method on the CampaignService
			collection = CampaignService.getCampaignInstance().getAllCampaign();
			assertNotNull( collection, "An Empty collection of Campaign was incorrectly returned.");
			
			// Now print out the values
			Campaign entity = null;            
			Iterator<Campaign> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getCampaignId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

